const contactId = $input.first().json.query?.contactId || $input.first().json.query?.contact_id || '';
if (!contactId) {
  throw new Error('Missing contactId query parameter');
}
return [{ json: { contactId } }];

// Build HTML release form page
const merged = $input.first().json;

// Contact data comes from Fetch GHL Contact (first input)
const contact = merged.contact || merged;

// Custom fields schema comes from Fetch Custom Fields Schema (second input)
// It may have failed (401) — handle gracefully
const allItems = $input.all();
let schemaFields = [];
for (const item of allItems) {
  if (item.json.customFields && Array.isArray(item.json.customFields)) {
    schemaFields = item.json.customFields;
    break;
  }
}

// Build field ID → name mapping from schema (if available)
const fieldNameMap = {};
for (const sf of schemaFields) {
  fieldNameMap[sf.id] = sf.name;
}

// Get custom fields from contact
const customFields = contact.customFields || [];

// Filter to RELEASE fields: if we have schema, filter by name starting with "RELEASE".
// If no schema, show ALL custom fields (user can refine later).
const releaseFields = [];
for (const cf of customFields) {
  const name = fieldNameMap[cf.id] || '';
  const isRelease = name.toLowerCase().startsWith('release');
  // Include if it's a RELEASE field, or if we have no schema (show all)
  if (isRelease || schemaFields.length === 0) {
    releaseFields.push({
      id: cf.id,
      name: name || `Field ${cf.id}`,
      value: cf.value
    });
  }
}

// Helper: format a field value for display
function formatValue(val) {
  if (val === null || val === undefined) return '<em>Not provided</em>';
  if (typeof val === 'string') return escapeHtml(val) || '<em>Not provided</em>';
  if (typeof val === 'object') {
    // Signature field
    if (val.url && val.meta && val.meta.isSignature) {
      return `<img src="${escapeHtml(val.url)}" alt="Signature" style="max-width:300px;border:1px solid #ccc;padding:4px;background:#fff;">`;
    }
    // File upload
    if (val.url) {
      return `<a href="${escapeHtml(val.url)}" target="_blank">View Attachment</a>`;
    }
    // Object with nested file entries (multiple uploads)
    const keys = Object.keys(val);
    if (keys.length === 0) return '<em>Not provided</em>';
    const links = [];
    for (const k of keys) {
      if (val[k] && val[k].url) {
        const fname = val[k].meta?.originalname || 'Attachment';
        links.push(`<a href="${escapeHtml(val[k].url)}" target="_blank">${escapeHtml(fname)}</a>`);
      }
    }
    return links.length > 0 ? links.join('<br>') : '<em>Not provided</em>';
  }
  return String(val);
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Standard contact fields
const firstName = contact.firstName || '';
const lastName = contact.lastName || '';
const fullName = `${firstName} ${lastName}`.trim() || 'Unknown';
const email = contact.email || '';
const phone = contact.phone || '';
const dob = contact.dateOfBirth || '';
const address = [contact.address1, contact.city, contact.state, contact.postalCode].filter(Boolean).join(', ');

// Build release fields HTML rows
let releaseFieldsHtml = '';
for (const rf of releaseFields) {
  const displayName = rf.name.replace(/^RELEASE\s*[-–—]\s*/i, '').trim() || rf.name;
  releaseFieldsHtml += `
    <tr>
      <td style="padding:8px 12px;font-weight:600;border-bottom:1px solid #e5e7eb;white-space:nowrap;vertical-align:top;">${escapeHtml(displayName)}</td>
      <td style="padding:8px 12px;border-bottom:1px solid #e5e7eb;">${formatValue(rf.value)}</td>
    </tr>`;
}

if (!releaseFieldsHtml) {
  releaseFieldsHtml = '<tr><td colspan="2" style="padding:12px;color:#6b7280;">No release form data found for this contact.</td></tr>';
}

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>TRX Release Form — ${escapeHtml(fullName)}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #f9fafb; color: #111827; padding: 24px; }
    .container { max-width: 800px; margin: 0 auto; }
    .header { background: #111827; color: #fff; padding: 20px 24px; border-radius: 8px 8px 0 0; }
    .header h1 { font-size: 22px; font-weight: 700; }
    .header p { font-size: 13px; color: #9ca3af; margin-top: 4px; }
    .card { background: #fff; border: 1px solid #e5e7eb; border-top: none; padding: 24px; margin-bottom: 24px; }
    .card:last-of-type { border-radius: 0 0 8px 8px; }
    .section-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: #6b7280; margin-bottom: 12px; }
    .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 20px; }
    .info-item label { display: block; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #9ca3af; }
    .info-item span { font-size: 15px; color: #111827; }
    table { width: 100%; border-collapse: collapse; }
    table th { text-align: left; padding: 8px 12px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: #9ca3af; border-bottom: 2px solid #e5e7eb; }
    @media print {
      body { padding: 0; background: #fff; }
      .header { background: #000 !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>TRX Tattoos &amp; Piercing — Release Form</h1>
      <p>Client Information &amp; Acknowledgements</p>
    </div>
    <div class="card">
      <div class="section-title">Client Information</div>
      <div class="info-grid">
        <div class="info-item"><label>Full Name</label><span>${escapeHtml(fullName)}</span></div>
        <div class="info-item"><label>Email</label><span>${escapeHtml(email)}</span></div>
        <div class="info-item"><label>Phone</label><span>${escapeHtml(phone)}</span></div>
        <div class="info-item"><label>Date of Birth</label><span>${escapeHtml(dob) || '<em>Not provided</em>'}</span></div>
        <div class="info-item" style="grid-column:span 2;"><label>Address</label><span>${escapeHtml(address) || '<em>Not provided</em>'}</span></div>
      </div>
    </div>
    <div class="card">
      <div class="section-title">Release Form Responses</div>
      <table>
        <thead><tr><th>Field</th><th>Response</th></tr></thead>
        <tbody>${releaseFieldsHtml}</tbody>
      </table>
    </div>
  </div>
</body>
</html>`;

return [{ json: { html } }];
